import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五十六章 什么人才是有智慧的人？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/56第五十六章 什么人才是有智慧的人.md","filePath":"meditation/巴利文大藏经/56第五十六章 什么人才是有智慧的人.md"}'),o={name:"meditation/巴利文大藏经/56第五十六章 什么人才是有智慧的人.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第五十六章-什么人才是有智慧的人" tabindex="-1">第五十六章 什么人才是有智慧的人？ <a class="header-anchor" href="#第五十六章-什么人才是有智慧的人" aria-label="Permalink to &quot;第五十六章 什么人才是有智慧的人？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部12相应19经/愚痴者贤智者经(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，世间人被无明（无明解释，见第四十九章）妨碍、障碍，被贪爱束缚捆绑，他们就会执着的认为世间的这个身体是真实存在的。当他们的眼睛、耳朵、鼻子、舌头、身体、内心接触到外界的物质事物、声音、气味、味道、触觉、思想，就会认识、分别、判断，产生喜欢、不喜欢的各种感受，也就是眼睛看见事物产生喜欢、不喜欢的感受；耳朵听到声音，产生喜欢、不喜欢的感受；鼻子闻到气味产生喜欢、不喜欢的感受；舌头尝到味道产生，喜欢、不喜欢的感受；身体触摸到事物或者身处在冷热等等的环境中，产生喜欢、不喜欢的感受，内心接触外界的事物或思想，产生喜欢、不喜欢的感受。这样世间的人就会产生喜怒哀乐等等的感受。</p><p>弟子们，世间又有两种人，一种是贤德有智慧的人，一种是愚昧无知的人，他们之间有什么不同呢？他们之间的差别是什么呢？”</p><p>出家弟子们说：“世尊，恭请您为我们说法，讲说贤德有智慧的人与愚昧无知的人，他们之间的差别。您是我们的导师，是您教导给我们修行的正法。您是我们的皈依，您的正法是我们的皈依，我们将会按世尊您的教导去精进修行的。”</p><p>佛陀说：“弟子们，你们要认真的听，你们要仔细的思考，如来现在为你们说法。”</p><p>出家弟子们说：“世尊，我们会认真听您说法的，我们会仔细的思考的。”</p><p>佛陀说：“愚昧无知的人，他们因为被无明（无明解释，见第四十九章）障碍、妨碍，因为被贪爱束缚捆绑，他们就会执着的认为世间的这个身体是真实存在的，那为什么他们的无明没有被除灭殆尽？为什么他们的贪爱没有被灭除殆尽呢？</p><p>弟子们，愚昧无知的人，他们没有去修习灭尽痛苦和烦恼的八正道（八正道解释，见第十八章）；他们没有受持戒律，没有让身体行为做善事而不做恶事，没有让口说善言而不说恶言，没有让内心生起善念而不生起恶念，他们没有除灭恶念，没有断恶修善，没有精进的去修行；他们没有除灭对世间一切事物事情的挂念和执着，没有除灭对善恶、福德罪恶、功德罪业的挂念和执着，没有除灭内心一切念想的挂念和执着。当他们死后，他们就会继续因为自己造下的福德罪业因果去投生，福德深厚的投生到富贵之家，上生到天界享福；福德薄弱的投生到贫贱之家，罪业深重的投生到地狱、饿鬼、畜生三恶道受苦。他们由此无有穷尽的生死轮回，无有穷尽的死去又再生。他们也由此无数次的产生出忧愁、悲伤、苦闷、忧虑、绝望等等烦恼和痛苦。他们无法从忧愁、悲伤、苦闷、忧虑、绝望、出生、衰老、死亡的烦恼和痛苦中解脱出来。他们在这些忧愁、悲伤、苦闷、忧虑、绝望、出生、衰老、死亡的烦恼和痛苦中循环往复、无有穷尽的煎熬和沉沦，受尽折磨，无法解脱出来。如来就说这样的人，他们无法从生死轮回的痛苦和烦恼中解脱出来，他们就是世间愚昧无知的人。</p><p>弟子们，贤德有智慧的人，他们修行灭尽痛苦和烦恼的八正道（八正道解释，见第十八章），他们受持戒律，让身体行为做善事而不做恶事，让口说善言而不说恶言，让内心生起善念而不生起恶念，他们除灭恶念，断恶修善，精进的去修行；他们除灭对世间一切事物事情的挂念和执着，除灭对善恶、福德罪恶、功德罪业的挂念和执着，除灭内心一切念想的挂念和执着。当他们死后，他们就不会继续因为自己造下的福德罪业因果去投生，就不会再生死轮回。因为没有出生在世间，他们也就不会产生出忧愁、悲伤、苦闷、忧虑、绝望等等烦恼和痛苦，他们就从忧愁、悲伤、苦闷、忧虑、绝望、出生、衰老、死亡的烦恼和痛苦中解脱了出来。他们就从世间忧愁、悲伤、苦闷、忧虑、绝望、出生、衰老、死亡的烦恼和痛苦轮回中永远的解脱出来。如来就说这样的人，他们能从痛苦和烦恼的生死轮回中永远的解脱出来，他们就是贤德有智慧的人。</p><p>弟子们，世间贤德有智慧的人与愚昧无知的人，他们的差别就是：是不是修行灭尽痛苦和烦恼的八正道，是不是受持戒律，是不是行为、言语、念想做善行不做恶行，是不是断恶修善，是不是为了除灭对世间一切事物事情的挂念和执着而修行，是不是为了除灭对善恶、福德罪恶、功德罪业的挂念和执着而修行，是不是为了除灭内心一切念想的挂念和执着而修行。如果是那么他们就是贤德有智慧的人，如果不是他们就是愚昧无知的人。简要的说就是：修行八正道，为了除灭贪爱，为了除灭对世间一切事物事情的挂念和执着去修行的人，他们就是贤德有智慧的人，反之他们就是世间愚昧无知的人。”</p><p>佛陀说法后，出家弟子们，都再次的顶礼佛陀，他们随喜赞叹佛陀说法的无量功德，都按着佛陀所说的法去修行。</p>',13)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
